#!/usr/bin/env python3
# reserve_L16d.py — 새 과 L16d(교환국 앞 거리)의 물건을 tools/hooks.json 「_심볼예약」 에 적는다(들여쓰기 1 · 끝 줄바꿈 없음 그대로).
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
T = '[2026-11-11 새 과 L16d]'
new = {
 '붉은 물길에 떠가는 흰 봉투 + 꼴 맞는 우편함 집': f'호르몬(내분비 신호) · 표적세포 전용 {T} — L16d s1 붉은 물길(혈류)을 따라 천천히 떠가는 흰 봉투(느리지만 오래) · s3 지붕 밑 우편함 꼴이 저마다 다른 작은 집 셋 중 봉투 꼴 우편함 집만 창에 노란 불(수용체가 있어야 반응). ⚠ 【사람이 손에서 손으로 건네는 흰 봉투】(내인자) · L20c#6 잎이 받쳐 든 흰 봉투(플로리겐)와 가른다 — 이쪽은 손이 아니라 물길에 떠간다.',
 '관 없는 양파 꼴 샘 집 / 홈통으로 물을 쏟는 집': f'내분비샘 / 외분비샘 전용 {T} — L16d s2. 양파 꼴 집은 관 하나 없이 흰 봉투를 붉은 물길로 곧장 떨어뜨리고(체액 · 혈류로) · 곁의 집은 홈통으로 맑은 물을 풀밭과 길바닥에 쏟는다(관을 거쳐 몸 겉 · 관 안으로 — 물길에는 한 방울도 안 감). 다시 그릴 때 홈통 물을 물길로 잇지 말 것(처음 바탕이 그렇게 그려 고쳤다).',
 '잔가지 팔 · 둥근 창 분홍 몸통 · 긴 검은 꼬리의 뉴런 짐승 + 꼬마 일꾼(흰 테이프 · 도시락) · 받침 나무 막대': f'뉴런 구조 · 시냅스 · 신경아교세포 전용 {T} — L16d s4(잔가지 팔 = 수상돌기 · 분홍 몸통 = 세포체 · 검은 꼬리 = 축삭 · 꼬리 끝 방울에서 옆집 문으로 뿜는 물방울 + 한 방향 분홍 화살 = 시냅스(화학 · 한 방향) · 테이프 감기 = 절연 · 도시락 = 영양 · 받침 막대 = 보조). s5 물길 가의 작은 분홍 뉴런이 검은 꼬리를 물길 위로 휘어 내려 끝 방울에서 흰 V 를 떨굼 = 신경내분비(ADH) — 꼬리 끝이 물길 위여야 뜻이 산다(처음 바탕은 꼬리가 길바닥 위였고 V 가 몸통 밑에서 떨어져 고쳤다).',
 '울타리 너머 이웃에게 날린 종이비행기': f'주변분비(국소 조절자 · 바로 옆까지만 가는 짧은 신호) 전용 {T} — L16d s7. 자가분비는 말로만(「제 집 문에 쪽지를 붙이듯」) — 그림에 없다.',
 '흰 가운이 던지는 작은 흰 쪽지 + 차례로 커지는 장난감 병정': f'사이토카인 전용 {T} — L16d s7(쪽지 = 사이토카인 · 병정 = 림프구가 자라고 분화). 병정 뜻은 【장난감 병정】(T 세포) 그대로.',
 '기름병을 짜 넣은 별 틀 · 날아가는 노란 별 · 빨갛게 부은 손': f'프로스타글란딘(지방산 · 아라키돈산에서 · 염증 · 통증 · 열) 전용 {T} — L16d s8. 「기름으로 찍은 별」 = 프로(스타)글란딘. 기름병 목의 금색 자물쇠 = 아스피린 · 이부프로펜(【금색 자물쇠】 그대로). 다른 판에 노란 별을 그리지 말 것.',
 '길바닥 단추 → 기둥 타고 오르는 줄 → 꼭대기 분홍 뇌 → 무릎에 묶인 둘째 줄 → 홱 드는 다리': f'반사 경로 · 중추 / 말초신경계 전용 {T} — L16d s9(밟힌 단추 = 자극 · 수용기 · 오르는 검은 줄 = 감각신경 · 꼭대기 뇌 + 높은 기둥 = 뇌 · 척수(CNS) · 기둥 옆 상자에서 무릎으로 내려와 묶인 검은 줄 = 운동신경 · 다리 = 반응기 · 두 줄 = 말초신경계). 둘째 줄은 Gemini 가 가늘게 그려 PIL 로 굵게 덧그었다 — 다시 그릴 때 둘째 줄을 빠뜨리지 말 것(운동신경이 사라진다).',
 '똑같은 빨간 개미 둘을 잇는 분홍 냄새 줄': f'페로몬(같은 종 개체 사이 · 몸 밖으로) 전용 {T} — L16d s10. 둘 다 오른쪽으로 간다 — 오른쪽 개미 꽁무니의 짧은 줄을 왼쪽 개미가 코끝으로 따라가고, 왼쪽 개미 뒤로도 긴 줄. 「앞 · 뒤」 말은 독자가 헷갈려 「오른쪽 · 왼쪽」으로 적었다. 다른 판에 개미를 그리지 말 것.',
 '금빛 고리 넷 덩이(육각 셋 + 오각 하나가 붙은 한 덩이)': f'스테로이드 골격 전용 {T} — L16d s11 노란 기름 유리 단지 입구에 걸침(기름에 녹음 · 콜레스테롤에서) + 곁의 코르크 마개(코르티솔). ★ Gemini 는 고리 수를 못 지킨다(따로 논 육각 다섯 → 「넷」을 부탁하자 벌집 일곱) — 고리 다섯을 지운 뒤 PIL(steroid.py)로 육각 셋 + 오각 하나를 그렸다. ⚠ 【벽에 걸린 오각판 둘 — 고리 넷】(리보스 · 디옥시리보스 — 오각판 하나에 -OH 고리 넷)과 가른다: 이쪽은 고리 넷이 서로 붙은 한 덩이.',
 '꼬리 달린 작은 금빛 고리 하나': f'아민 호르몬(아미노산 하나에서 · 에피네프린 · 티록신) 전용 {T} — L16d s11 뚜껑 터진 드럼통 입구에 걸림. ⚠ 독자가 「9 · Q · 올챙이」로도 읽는다 — 늘 드럼통과 함께 그려 뜻을 붙든다.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('검은 전선', f'★ {T} L16d s1 전봇대 사이 검은 전선 위를 번쩍 내닫는 노란 불꽃 = 신경 신호(빠르고 짧게) · s4 뉴런 짐승의 긴 검은 꼬리(축삭) · s5 작은 뉴런의 꼬리 · s9 반사의 두 줄(감각 · 운동신경) — 모두 신경.')
add('V자 이음쇠', f'★ {T} L16d s5 작은 분홍 뉴런의 꼬리 끝 방울에서 붉은 물길로 떨어지는 흰 V 조각 = 신경내분비의 대표 ADH(시상하부 뉴런 → 후엽 → 혈액).')
add('노 젓는 사람', f'★ {T} L16d s6 통처럼 부푼 붉은 물길에서 노 젓는 사람 + 물길을 가로지른 투명한 장막을 찢지 않고 지나감 = NO(혈관 확장 · 기체라 막 통과 · 국소 조절자). ⚠ 장막에 구멍 · 아치 자국이 있으면 「뚫고 지나감」으로 읽힌다(처음 바탕이 그래서 메웠다).')
add('장난감 병정(작은 나무 인형 병사)', f'★ {T} L16d s7 흰 가운이 던진 쪽지(사이토카인)를 받고 차례로 키가 커지는 나무 병정 넷 = 림프구의 성장 · 분화.')
add('금색 자물쇠', f'★ {T} L16d s8 노란 기름병 목에 채운 금색 자물쇠 = 아스피린 · 이부프로펜(프로스타글란딘 합성 억제).')
add('뚜껑이 터진 드럼통', f'★ {T} L16d s11 작업대 오른쪽 — 뚜껑이 날아간 쇠 드럼통 입구의 꼬리 달린 작은 고리 = 아민 호르몬(에피네프린). 처음 바탕은 작은북으로 그려 Gemini 로 드럼통을 다시 그렸다.')
add('코르크 마개', f'★ {T} L16d s11 노란 기름 단지 곁의 코르크 마개 = 코르티솔(스테로이드의 예).')
add('사람이 치켜든 주사기', f'★ {T} L16d s11 한 손에 구슬 사슬을 쥔 간호사가 다른 손에 치켜든 주사기 = 인슐린(폴리펩타이드 호르몬의 예).')
add('구슬 — 빛깔과 놓인 곳으로 가름', f'★ {T} L16d s11 물대야에 늘어져 뜬 긴 구슬 사슬 = 폴리펩타이드(아미노산을 줄줄이 · 물에 녹음).')
add('등에 멘 노란 기름방울 · 우윳빛 흰 길', f'★ {T} L16d s8 요리사의 노란 기름병(지방산 → 프로스타글란딘) · s11 노란 기름 유리 단지(스테로이드는 기름에 녹는다) — 노란 기름 = 지질 · 지용성 그대로.')
open(P, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=1))
print('예약', len(R))
